---
/**
 * [...slug].astro — every note page.
 *
 * One route per published note: getStaticPaths() walks getCollection('notes') and emits a path per
 * entry, keyed by the Quartz slug (`simplifySlug(entry.id)`), SKIPPING the home entry (simplifySlug
 * === '/') which index.astro owns. Each path carries its entry as a prop.
 *
 * Rendering: `render(entry)` gives the compiled <Content/> + Astro `headings`. The global link graph
 * and backlink index are built ONCE (module-level memo, shared across every generated page) over all
 * notes, then sliced per note — localGraph(graph, id, 2) for the rail, backlinks[id] for the panel.
 * Title via deriveTitle, domain via resolveDomain. Everything is handed to <Note/>, which wraps Base.
 */
import { getCollection, render } from 'astro:content';
import type { GetStaticPaths } from 'astro';
import Note from '../layouts/Note.astro';
import { deriveTitle } from '../lib/note';
import { resolveDomain } from '../lib/domain';
import { simplifySlug } from '../lib/slug';
import { buildGraph, localGraph, type NoteInput as GraphNoteInput } from '../lib/graph';
import { buildBacklinks, type NoteInput as BacklinkNoteInput } from '../lib/backlinks';
import type { GraphData, BacklinkIndex } from '../lib/types';

export const getStaticPaths = (async () => {
  const notes = await getCollection('notes');
  return notes
    // index.md (simplifySlug → '/') is rendered by index.astro; notes/index by notes.astro.
    .filter((entry) => simplifySlug(entry.id) !== '/' && entry.id !== 'notes/index')
    .map((entry) => ({
      params: { slug: simplifySlug(entry.id) },
      props: { entry },
    }));
}) satisfies GetStaticPaths;

/* ── module-level memo: build the global graph + backlinks exactly once ─────── */
let graphMemo: GraphData | null = null;
let backlinksMemo: BacklinkIndex | null = null;

async function getGlobalIndices(): Promise<{ graph: GraphData; backlinks: BacklinkIndex }> {
  if (graphMemo && backlinksMemo) return { graph: graphMemo, backlinks: backlinksMemo };
  const notes = await getCollection('notes');
  const graphInput: GraphNoteInput[] = notes.map((n) => ({
    slug: n.id,
    title: deriveTitle(n.data, n.id, n.body),
    type: typeof n.data.type === 'string' ? n.data.type : '',
    body: n.body ?? '',
  }));
  const backlinkInput: BacklinkNoteInput[] = notes.map((n) => ({
    slug: n.id,
    title: deriveTitle(n.data, n.id, n.body),
    body: n.body ?? '',
  }));
  graphMemo = buildGraph(graphInput);
  backlinksMemo = buildBacklinks(backlinkInput);
  return { graph: graphMemo, backlinks: backlinksMemo };
}

const { entry } = Astro.props as { entry: Awaited<ReturnType<typeof getCollection>>[number] };

const { Content, headings } = await render(entry);

const title = deriveTitle(entry.data, entry.id, entry.body);
const domain = resolveDomain(entry.id);
const type = typeof entry.data.type === 'string' ? entry.data.type : undefined;
const updated =
  entry.data.updated instanceof Date
    ? entry.data.updated.toISOString().slice(0, 10)
    : typeof entry.data.updated === 'string'
      ? entry.data.updated
      : undefined;

const { graph, backlinks } = await getGlobalIndices();
const local = localGraph(graph, entry.id, 2);
const noteBacklinks = backlinks[entry.id] ?? [];

// Astro headings → the {depth,text,slug} shape Toc/Note expect.
const tocHeadings = headings.map((h) => ({ depth: h.depth, text: h.text, slug: h.slug }));
---

<Note
  title={title}
  type={type}
  updated={updated}
  domain={domain}
  slug={entry.id}
  headings={tocHeadings}
  backlinks={noteBacklinks}
  local={local}
>
  <Content />
</Note>

---
/**
 * Chrome.astro — sticky top bar. Ported pixel-for-pixel from the DS KB
 * screens.jsx <Chrome> (sticky header variant) + styles.html .chrome.
 *
 * Brand lockup (mark-nodes-violet + "Knowledge base" + "second brain" kicker),
 * nav with .on active state, theme-toggle button (#theme-toggle, wired by Base),
 * and one inline search field (dropdown results, no modal).
 */
interface Props {
  /** Active nav id — one of "map" | "notes" | "projects" | "journal" | "personal" | "about". */
  active?: string;
}
const { active } = Astro.props;

const nav: { id: string; label: string; href: string }[] = [
  { id: 'map', label: 'Map', href: '/map' },
  { id: 'notes', label: 'Notes', href: '/notes' },
  { id: 'projects', label: 'Projects', href: '/projects' },
  { id: 'journal', label: 'Journal', href: '/journal' },
  { id: 'personal', label: 'Personal', href: '/personal' },
  { id: 'about', label: 'About', href: '/about' },
];
---

<header class="kb-chrome">
  <div class="kb-chrome__inner">
    <a class="kb-brand" href="/">
      <svg class="kb-brand__mark" viewBox="0 0 104 104" width="30" height="30" role="img" aria-label="Logos52" fill="none">
        <g stroke="currentColor" stroke-width="5" stroke-linecap="round">
          <path d="M52 52 L28 52 M52 52 L66 80" />
        </g>
        <g fill="currentColor">
          <circle cx="28" cy="52" r="8" />
          <circle cx="66" cy="80" r="8" />
          <circle cx="80" cy="32" r="7" />
          <circle cx="52" cy="52" r="12" />
        </g>
      </svg>
      <span class="kb-brand__name">Logos52</span>
    </a>
    <nav class="kb-nav">
      {nav.map((n) => (
        <a href={n.href} class:list={['kb-nav__link', { on: active === n.id }]}>
          {n.label}
        </a>
      ))}
    </nav>
    <span class="kb-spacer"></span>
    <button
      type="button"
      id="theme-toggle"
      class="kb-theme-toggle"
      title="Toggle theme"
      aria-label="Toggle theme"
    >
      <span class="kb-theme-toggle__light">☾</span>
      <span class="kb-theme-toggle__dark">☀</span>
    </button>
    <div class="kb-search" data-inline-search>
      <input
        type="search"
        class="kb-search-input"
        data-search-input
        placeholder="Find a note… (⌘K)"
        aria-label="Search notes"
        autocomplete="off"
      />
      <div class="kb-search-results" data-search-results hidden></div>
    </div>
    <button type="button" class="kb-menu-btn" id="kb-menu-btn" aria-label="Open menu" aria-expanded="false">
      ☰
    </button>
  </div>
</header>

<style>
  /* header — sticky, blurred paper, hairline rule (screens.jsx L24) */
  .kb-chrome {
    position: sticky;
    top: 0;
    z-index: 30;
    background: color-mix(in oklab, var(--paper) 88%, transparent);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--rule);
  }
  .kb-chrome__inner {
    max-width: var(--kb-content);
    margin: 0 auto;
    padding: 0 28px;
    display: flex;
    align-items: center;
    gap: 24px;
    height: 60px;
  }

  /* brand lockup (screens.jsx L26–29) */
  .kb-brand {
    display: flex;
    align-items: center;
    gap: 11px;
    font-weight: 700;
    font-size: 17px;
    color: var(--ink);
    text-decoration: none;
  }
  .kb-brand__mark {
    width: 30px;
    height: 30px;
    flex: none;
    /* node glyph, no seal badge, transparent — a vivid purple brand mark with pop,
     * brightened a touch more on charcoal so it reads. */
    color: #7c3aed;
  }
  :global([data-theme='dark']) .kb-brand__mark {
    color: #a78bfa;
  }
  .kb-brand__name {
    white-space: nowrap;
  }
  .kb-brand__kicker {
    font-family: var(--mono);
    font-size: 10px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--faint);
    font-weight: 400;
  }

  /* nav (screens.jsx L11–22, L30–32) */
  .kb-nav {
    display: flex;
    gap: 4px;
    margin-left: 8px;
  }
  .kb-nav__link {
    font-family: var(--sans);
    font-size: var(--kb-text-sm);
    color: var(--mut);
    background: transparent;
    border: none;
    padding: 6px 12px;
    border-radius: var(--tsg-radius-sm);
    text-decoration: none;
    cursor: pointer;
  }
  .kb-nav__link.on {
    color: var(--accent);
    background: var(--accent-soft);
  }

  .kb-spacer {
    flex: 1;
  }

  /* theme toggle pill (screens.jsx L34) */
  .kb-theme-toggle {
    font-family: var(--sans);
    font-size: 14px;
    color: var(--mut);
    background: none;
    border: 1px solid var(--rule2);
    border-radius: 999px;
    padding: 5px 12px;
    cursor: pointer;
    margin-right: 10px;
    line-height: 1;
  }
  /* show the glyph matching the *current* theme target (☾ in light, ☀ in dark) */
  .kb-theme-toggle__dark {
    display: none;
  }
  :global(html[data-theme='dark']) .kb-theme-toggle__light {
    display: none;
  }
  :global(html[data-theme='dark']) .kb-theme-toggle__dark {
    display: inline;
  }

  /* inline search — compact input + dropdown (no modal, no blur) */
  .kb-search {
    position: relative;
  }
  .kb-search-input {
