/**
 * search-inline.ts — inline dropdown search over the Pagefind full-body index.
 * No modal, no backdrop blur: results drop down right under the input. Keyboard ↑ ↓ Enter Esc, ⌘K focus.
 * Wire on any element containing `[data-search-input]` + `[data-search-results]`.
 */
import { loadPagefind } from '../lib/pagefind-client';
import { DOMAIN_LABELS, isDomain } from '../lib/types';

/** Warm Pagefind after idle so first keystroke doesn't hitch the main thread. */
function preloadPagefind(): void {
  const run = () => void loadPagefind(18).catch(() => {});
  if ('requestIdleCallback' in window) {
    requestIdleCallback(run, { timeout: 2500 });
  } else {
    setTimeout(run, 800);
  }
}

const domainLabel = (raw?: string) => (raw && isDomain(raw) ? DOMAIN_LABELS[raw] : (raw ?? ''));
const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let cmdKBound = false;

export function initInlineSearch(root: HTMLElement): void {
  const input = root.querySelector<HTMLInputElement>('[data-search-input]');
  const list = root.querySelector<HTMLElement>('[data-search-results]');
  if (!input || !list) return;

  let active = -1;
  let rows: { url: string; title: string; domain: string; excerpt: string }[] = [];

  const show = (v: boolean) => {
    list.hidden = !v;
    root.classList.toggle('open', v);
  };

  const render = () => {
    list.innerHTML = '';
    if (!input.value.trim()) return show(false);
    if (!rows.length) {
      list.innerHTML = '<p class="kb-ac-empty">No notes found.</p>';
      return show(true);
    }
    rows.forEach((r, i) => {
      const a = document.createElement('a');
      a.href = r.url;
      a.className = 'kb-ac-row' + (i === active ? ' on' : '');
      a.innerHTML =
        `<span class="kb-ac-title">${esc(r.title)}</span>` +
        (r.domain ? `<span class="kb-ac-domain">${esc(r.domain)}</span>` : '') +
        (r.excerpt ? `<span class="kb-ac-ex">${esc(r.excerpt)}</span>` : '');
      a.addEventListener('mousedown', (e) => {
        e.preventDefault();
        window.location.href = r.url;
      });
      list.append(a);
    });
    show(true);
  };

  let timer: ReturnType<typeof setTimeout> | undefined;
  const run = async (q: string) => {
    if (!q.trim()) {
      rows = [];
      return render();
    }
    try {
      const api = await loadPagefind(18);
      const { results } = await api.search(q.trim());
      rows = await Promise.all(
        results.slice(0, 8).map(async (h) => {
          const d = await h.data();
          return {
            url: d.url,
            title: d.meta.title ?? d.url.split('/').filter(Boolean).pop() ?? 'Note',
            domain: domainLabel(d.meta.domain),
            excerpt: d.excerpt?.trim() || '',
          };
        }),
      );
      active = -1;
      render();
    } catch {
      list.innerHTML = '<p class="kb-ac-empty">Search index loading…</p>';
      show(true);
    }
  };

  input.addEventListener('input', () => {
    clearTimeout(timer);
    timer = setTimeout(() => void run(input.value), 110);
  });
  input.addEventListener('focus', () => {
    if (input.value.trim()) render();
  });
  input.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      active = Math.min(active + 1, rows.length - 1);
      render();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      active = Math.max(active - 1, 0);
      render();
    } else if (e.key === 'Enter') {
      const pick = rows[active] ?? rows[0];
      if (pick) {
        e.preventDefault();
        window.location.href = pick.url;
      }
    } else if (e.key === 'Escape') {
      show(false);
      input.blur();
    }
  });

  document.addEventListener('click', (e) => {
    if (!root.contains(e.target as Node)) show(false);
  });

  if (!cmdKBound) {
    cmdKBound = true;
    preloadPagefind();
    document.addEventListener('keydown', (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        document.querySelector<HTMLInputElement>('.kb-chrome [data-search-input]')?.focus();
      }
    });
  }
}

/**
 * pagefind-client.ts — load the Pagefind UI bundle at runtime (never via Vite import).
 *
 * Pagefind is emitted to dist/pagefind/ at build time; astro-pagefind serves it from dist/
 * during `astro dev`. A static `import('/pagefind/pagefind.js')` makes Vite try to resolve the
 * path at transform time and fails — this loader injects a module script in the browser instead.
 */

export type PagefindResult = {
  data: () => Promise<{
    url: string;
    meta: Record<string, string>;
    excerpt: string;
    content?: string;
  }>;
};

export type PagefindAPI = {
  options: (o: Record<string, unknown>) => Promise<void>;
  search: (q: string) => Promise<{ results: PagefindResult[] }>;
};

type WindowWithPagefind = Window & { __kbPagefind?: PagefindAPI };

const caches = new Map<number, Promise<PagefindAPI>>();

export function loadPagefind(excerptLength: number): Promise<PagefindAPI> {
  const cached = caches.get(excerptLength);
  if (cached) return cached;

  const promise = new Promise<PagefindAPI>((resolve, reject) => {
    const win = window as WindowWithPagefind;
    if (win.__kbPagefind) {
      void win.__kbPagefind.options({ excerptLength }).then(() => resolve(win.__kbPagefind!));
      return;
    }

    const onReady = () => {
      const api = win.__kbPagefind;
      if (!api) {
        reject(new Error('Pagefind module loaded but API missing'));
        return;
      }
      void api.options({ excerptLength }).then(() => resolve(api));
    };

    window.addEventListener('kb-pagefind-ready', onReady, { once: true });

    const boot = document.createElement('script');
    boot.type = 'module';
    boot.textContent = `
      import * as m from '/pagefind/pagefind.js';
      window.__kbPagefind = m;
      window.dispatchEvent(new CustomEvent('kb-pagefind-ready'));
    `;
    boot.onerror = () => {
      window.removeEventListener('kb-pagefind-ready', onReady);
      reject(
        new Error(
          'Pagefind index not found. Run `npm run build` once, then `npm run dev`.',
        ),
      );
    };
    document.head.append(boot);
  });

  caches.set(excerptLength, promise);
  return promise;
}

/**
 * slug.ts — Quartz-identical slug derivation.
 *
 * Ported verbatim from quartz/util/path.ts (`sluggify` / `slugifyFilePath` / `simplifySlug`) so the
 * Astro site's URLs stay 1:1 with the old Quartz paths (preserves inbound links + SEO). Pure, no deps.
 */

/** Slugify a path segment-wise, exactly as Quartz does. */
export function sluggify(s: string): string {
  return s
    .split('/')
    .map((seg) =>
      seg
        .replace(/\s/g, '-')
        .replace(/&/g, '-and-')
        .replace(/%/g, '-percent')
        .replace(/\?/g, '')
        .replace(/#/g, ''),
    )
    .join('/')
    .replace(/\/$/, '');
}

/**
 * Vault-relative `.md` path → full slug (no extension). `_index`/`index` preserved as `index`.
 * e.g. "wiki/Books/The Parasitic Mind.md" → "wiki/Books/The-Parasitic-Mind"; "notes/index.md" → "notes/index".
 */
export function slugifyFilePath(fp: string): string {
  let s = fp.replace(/^\/+/, '').replace(/\/+$/, '');
  s = s.replace(/\.(md|html)$/i, '');
  s = sluggify(s);
  if (s.endsWith('_index')) s = s.replace(/_index$/, 'index');
  return s;
}

/** Full slug → simple slug (trailing "index" trimmed; empty → "/"). Matches Quartz `simplifySlug`. */
export function simplifySlug(slug: string): string {
  let s = slug.replace(/\/?index$/, '');
  s = s.replace(/^\/+|\/+$/g, '');
  return s.length === 0 ? '/' : s;
}

/** Full slug → site URL path (folder-based, leading + trailing slash; root → "/"). */
export function slugToUrl(slug: string): string {
  const simple = simplifySlug(slug);
  return simple === '/' ? '/' : `/${simple}/`;
}

/** Last path segment of a slug (used for default link text + basename resolution). */
export function basename(slug: string): string {
  const parts = slug.split('/').filter(Boolean);
  return parts[parts.length - 1] ?? slug;
}

import { existsSync, readFileSync } from 'node:fs';
import { defineConfig } from 'astro/config';
import sitemap from '@astrojs/sitemap';
import pagefind from 'astro-pagefind';
import { remarkWikilinks } from './src/lib/wikilinks';

function loadRedirects(): Record<string, string> {
  const path = 'kb-astro/site-data/redirects.json';
  if (!existsSync(path)) return {};
  try {
    const items = JSON.parse(readFileSync(path, 'utf8')) as { from: string; to: string }[];
    return Object.fromEntries(items.map(({ from, to }) => [from, to]));
  } catch {
    return {};
  }
}

// Logos52 knowledge base — re-platformed from Quartz to Astro.
// - GitHub Pages user site → site root is https://logos52.github.io/, no base path.
// - Folder-based URLs (`build.format: 'directory'`) so slugs stay 1:1 with the old Quartz paths.
// - Pagefind builds a full-body search index from the rendered HTML at build time.
export default defineConfig({
  site: 'https://logos52.github.io',
  trailingSlash: 'ignore',
  build: { format: 'directory' },
  redirects: loadRedirects(),
  integrations: [sitemap(), pagefind()],
  vite: {
    plugins: [
      {
        name: 'external-pagefind',
        enforce: 'pre',
        resolveId(id) {
          if (id === '/pagefind/pagefind.js' || id.startsWith('/pagefind/')) {
            return { id, external: true };
          }
        },
      },
    ],
  },
  markdown: {
    remarkPlugins: [remarkWikilinks],
    shikiConfig: {
      themes: { light: 'github-light', dark: 'github-dark' },
      wrap: true,
    },
  },
});

---
/**
 * Base.astro — the document shell for the KB Astro site.
 *
 * Owns:
 *  - <html lang="en" data-accent="violet"> (KB look) — dark mode via [data-theme="dark"].
 *  - The DS CSS imports, ONCE (styles.css = font + token manifest; domains.css = --d-* hues).
 *  - A no-flash inline script that sets data-theme from localStorage('theme') or
 *    prefers-color-scheme BEFORE first paint.
 *  - <Chrome/> + <slot/> + <Footer/>.
 *  - A small client script wiring #theme-toggle to flip [data-theme] + persist localStorage.
 *
 * No other component re-imports global CSS (ground rule).
 */
import '../styles/ds/styles.css';
import '../styles/ds/domains.css';
import '../styles/ds/flavors-preview.css'; // TEMP: cool-neutral palette preview (?palette=slate|overcast|charcoal)
import Chrome from '../components/Chrome.astro';
import Footer from '../components/Footer.astro';

interface Props {
  title: string;
  description?: string;
  /** Active nav id passed through to Chrome (atlas | notes | projects | about). */
  active?: string;
}
const { title, description, active } = Astro.props;
---

<!doctype html>
<html lang="en" data-accent="violet" data-palette="slate">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <link rel="icon" href="/favicon-nodes.svg" type="image/svg+xml" />
    <title>{title}</title>
    {description && <meta name="description" content={description} />}

    {/* No-flash theme: resolve before paint, set data-theme on <html>. */}
    <script is:inline>
      (function () {
        try {
          var stored = localStorage.getItem('theme');
          var theme =
            stored === 'dark' || stored === 'light'
              ? stored
              : window.matchMedia &&
                  window.matchMedia('(prefers-color-scheme: dark)').matches
                ? 'dark'
                : 'light';
          document.documentElement.setAttribute('data-theme', theme);
        } catch (e) {
          document.documentElement.setAttribute('data-theme', 'light');
        }
      })();
    </script>

    {/* TEMP palette preview: ?palette=slate|overcast|charcoal (persists), default slate. */}
    <script is:inline>
      (function () {
        try {
          var valid = { slate: 1, overcast: 1, charcoal: 1 };
          var p = new URLSearchParams(location.search).get('palette');
          if (!valid[p]) p = localStorage.getItem('palette');
          if (!valid[p]) p = 'slate';
          document.documentElement.setAttribute('data-palette', p);
          try { localStorage.setItem('palette', p); } catch (e) {}
        } catch (e) {
          document.documentElement.setAttribute('data-palette', 'slate');
        }
      })();
    </script>
  </head>
  <body>
    <Chrome active={active} />
    <slot />
    <Footer />

    {/* Theme toggle: flip [data-theme] on <html>, persist to localStorage('theme'). */}
    <script is:inline>
      (function () {
        var btn = document.getElementById('theme-toggle');
        if (!btn) return;
        btn.addEventListener('click', function () {
          var html = document.documentElement;
          var next =
            html.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
          html.setAttribute('data-theme', next);
          try {
            localStorage.setItem('theme', next);
          } catch (e) {}
        });
      })();
    </script>

    {/* Inline dropdown search — chrome bar only; no modal overlay. */}
    <script>
      import { initInlineSearch } from '../islands/search-inline';
      document
        .querySelectorAll('[data-inline-search]')
        .forEach((el) => initInlineSearch(el as HTMLElement));
    </script>
  </body>
</html>

<style is:global>
  html {
    /* Paper & Ink base surface — tokens own the actual values. */
    --kb-content: 880px; /* global content width → uniform side whitespace across every page */
    background: var(--paper);
    color: var(--ink);
  }
  body {
    margin: 0;
    background: var(--paper);
    color: var(--ink);
    font-family: var(--sans);
    line-height: 1.5;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
  }
  /* The <slot/> content (main) takes the remaining height so the footer sinks. */
  body > :global(main) {
    flex: 1;
  }
  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  /* inline search dropdown — shared; rows are injected by src/islands/search-inline.ts */
  [data-search-results] {
    position: absolute;
    z-index: 40;
    margin-top: 6px;
    background: var(--card);
    border: 1px solid var(--rule);
    border-radius: var(--tsg-radius-sm);
    box-shadow: var(--tsg-shadow-md, var(--tsg-shadow));
    padding: 6px;
    max-height: 62vh;
    overflow-y: auto;
  }
  [data-search-results][hidden] {
    display: none;
  }
  .kb-ac-row {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 2px 10px;
    align-items: baseline;
    padding: 8px 10px;
    border-radius: 8px;
    text-decoration: none;
    color: var(--ink);
  }
  .kb-ac-row.on,
  .kb-ac-row:hover {
    background: var(--accent-soft);
  }
  .kb-ac-title {
    font-family: var(--ming);
    font-size: var(--kb-text-base);
  }
  .kb-ac-domain {
    font-family: var(--mono);
    font-size: var(--kb-text-2xs);
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--accent);
    white-space: nowrap;
  }
  .kb-ac-ex {
    grid-column: 1 / -1;
    font-size: var(--kb-text-xs);
    color: var(--mut);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .kb-ac-empty {
    padding: 12px;
    color: var(--faint);
    font-size: var(--kb-text-sm);
    margin: 0;
  }
</style>

