const SPINE_MAX_HUB_LINKS_PER_HUB = 3;
const SPINE_EXTRA_PERIPHERAL_LINKS = 15;
const SPINE_OUTLINE_PERIMETER_LINKS = 4;
const SELF_REG_HUB = 'wiki/Dimensions/Self-Regulation';
